import os
import hashlib
import hmac
import tempfile
import threading
import time
from pathlib import Path
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

SESSION_DIR = Path(tempfile.mkdtemp(prefix="sessions_"))
SECRET_KEY = os.urandom(32)
SESSION_LOCK = threading.Lock()

def compute_session_mac(session_id: str, user_id: str) -> str:
    """Compute HMAC for session integrity verification."""
    msg = f"{session_id}:{user_id}".encode('utf-8')
    return hmac.new(SECRET_KEY, msg, hashlib.sha256).hexdigest()

def sanitize_session_id(session_id: str) -> str:
    """Strictly validate and sanitize session ID to prevent path traversal."""
    if not session_id or len(session_id) != 64:
        return None
    # Only allow hex characters
    if not all(c in '0123456789abcdef' for c in session_id):
        return None
    return session_id

def get_session_path(session_id: str) -> Path:
    """Get the canonical session file path."""
    sanitized = sanitize_session_id(session_id)
    if sanitized is None:
        return None
    path = SESSION_DIR / f"{sanitized}.session"
    # Verify the resolved path is within SESSION_DIR
    try:
        resolved = path.resolve()
        if not str(resolved).startswith(str(SESSION_DIR.resolve())):
            return None
    except (OSError, ValueError):
        return None
    return path

def verify_session_ownership(session_path: Path, claimed_user: str) -> bool:
    """Verify that the session file belongs to the claimed user.

    Reads the session file and checks the stored user_id matches.
    This is a security-critical ownership verification step.
    """
    try:
        with open(session_path, 'r') as f:
            stored_data = f.read().strip()
        parts = stored_data.split('\n')
        if len(parts) != 3:
            return False
        stored_user = parts[0]
        stored_mac = parts[2]
        # Verify MAC integrity
        expected_mac = compute_session_mac(session_path.stem, stored_user)
        if not hmac.compare_digest(stored_mac, expected_mac):
            return False
        return stored_user == claimed_user
    except (IOError, OSError, IndexError):
        return False

def read_session_data(session_path: Path) -> dict:
    """Read session payload data from verified session file."""
    try:
        with open(session_path, 'r') as f:
            stored_data = f.read().strip()
        parts = stored_data.split('\n')
        if len(parts) != 3:
            return None
        return {"user": parts[0], "data": parts[1], "mac": parts[2]}
    except (IOError, OSError, IndexError):
        return None

@app.route('/session/create', methods=['POST'])
def create_session():
    """Create a new session for authenticated user."""
    user_id = request.json.get('user_id', '')
    payload = request.json.get('data', '')

    if not user_id or len(user_id) > 64:
        abort(400)
    if '\n' in user_id or '\r' in user_id:
        abort(400)
    if '\n' in payload or '\r' in payload:
        abort(400)
    if len(payload) > 1024:
        abort(400)

    session_id = hashlib.sha256(os.urandom(32)).hexdigest()
    session_path = get_session_path(session_id)
    if session_path is None:
        abort(500)

    mac = compute_session_mac(session_id, user_id)
    content = f"{user_id}\n{payload}\n{mac}"

    with SESSION_LOCK:
        with open(session_path, 'w') as f:
            f.write(content)

    return jsonify({"session_id": session_id})

@app.route('/session/read', methods=['POST'])
def read_session():
    """Read session data - verifies ownership then returns data.

    Security model: Atomically verify ownership and read data under lock
    to prevent TOCTOU race conditions.
    """
    session_id = request.json.get('session_id', '')
    claimed_user = request.json.get('user_id', '')

    session_path = get_session_path(session_id)
    if session_path is None:
        abort(404)

    if not session_path.exists():
        abort(404)

    # Atomically verify ownership AND read data under the same lock
    # to prevent TOCTOU between check and use
    with SESSION_LOCK:
        is_owner = verify_session_ownership(session_path, claimed_user)
        if not is_owner:
            abort(403)

        # Read data while still holding lock - no race window
        data = read_session_data(session_path)

    if data is None:
        abort(500)

    return jsonify(data)

@app.route('/session/update', methods=['POST'])
def update_session():
    """Update session data - allows changing payload for own sessions."""
    session_id = request.json.get('session_id', '')
    claimed_user = request.json.get('user_id', '')
    new_payload = request.json.get('data', '')

    if '\n' in new_payload or '\r' in new_payload:
        abort(400)
    if len(new_payload) > 1024:
        abort(400)

    session_path = get_session_path(session_id)
    if session_path is None:
        abort(404)

    with SESSION_LOCK:
        if not verify_session_ownership(session_path, claimed_user):
            abort(403)

        # Rewrite session with new data
        mac = compute_session_mac(session_id, claimed_user)
        content = f"{claimed_user}\n{new_payload}\n{mac}"
        with open(session_path, 'w') as f:
            f.write(content)

    return jsonify({"status": "updated"})

@app.route('/session/transfer', methods=['POST'])
def transfer_session():
    """Transfer session ownership to another user.

    This replaces the session file content with new owner info.
    Used for account delegation scenarios.
    """
    session_id = request.json.get('session_id', '')
    current_user = request.json.get('user_id', '')
    new_owner = request.json.get('new_owner', '')

    if not new_owner or len(new_owner) > 64:
        abort(400)
    if '\n' in new_owner or '\r' in new_owner:
        abort(400)

    session_path = get_session_path(session_id)
    if session_path is None:
        abort(404)

    with SESSION_LOCK:
        if not verify_session_ownership(session_path, current_user):
            abort(403)

        # Transfer: rewrite with new owner, preserve data
        data = read_session_data(session_path)
        if data is None:
            abort(500)

        mac = compute_session_mac(session_id, new_owner)
        content = f"{new_owner}\n{data['data']}\n{mac}"
        with open(session_path, 'w') as f:
            f.write(content)

    return jsonify({"status": "transferred", "new_owner": new_owner})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, threaded=True)
